/* ---------- Database layer (browser storage, falls back to memory) ---------- */
const KEY='supply.ledger.v2';let mem=null,db;
const now=()=>new Date().toLocaleString();
function seed(){const P=[{sku:'LAP-LAT',name:'Dell Latitude laptop',qty:4,threshold:5,target:20},{sku:'MSE-WL',name:'Wireless mouse',qty:32,threshold:15,target:60},{sku:'KBD-MK',name:'Mechanical keyboard',qty:12,threshold:10,target:30},{sku:'HDMI-2M',name:'HDMI cable 2 m',qty:9,threshold:10,target:40},{sku:'SSD-1T',name:'1 TB SSD drive',qty:6,threshold:5,target:15},{sku:'RTR-AX',name:'Wi-Fi 6 router',qty:3,threshold:4,target:12}];
 return{products:P,moves:P.map(p=>({t:now(),sku:p.sku,type:'IN',qty:p.qty,after:p.qty,note:'Initial stock'}))}}
function load(){try{const r=localStorage.getItem(KEY);if(r)return JSON.parse(r)}catch(e){}return mem||seed()}
function save(){mem=db;try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){}}

/* ---------- Business rules (pure functions, work on any db copy) ---------- */
const isInt=n=>Number.isInteger(n);
function checkProduct(d,p,editing){
 if(!p.sku||!/^[A-Za-z0-9-]+$/.test(p.sku))return'SKU is required and may only use letters, digits and hyphens.';
 if(!editing&&d.products.some(x=>x.sku.toLowerCase()===p.sku.toLowerCase()))return'SKU '+p.sku+' already exists. SKUs must be unique.';
 if(!p.name.trim())return'Product name is required.';
 if(!isInt(p.qty)||p.qty<0)return'Stock cannot be negative and must be a whole number.';
 if(!isInt(p.threshold)||p.threshold<0)return'Minimum threshold must be a whole number of 0 or more.';
 if(!isInt(p.target)||p.target<=p.threshold)return'Target stock must be greater than the threshold.';
 return null}
const reorder=p=>p.qty<=p.threshold?Math.max(0,p.target-p.qty):0;
function addProduct(d,p){const e=checkProduct(d,p,false);if(e)return{ok:false,msg:e};
 d.products.push({...p});d.moves.push({t:now(),sku:p.sku,type:'IN',qty:p.qty,after:p.qty,note:'Initial stock'});return{ok:true,msg:'Added '+p.sku+'.'}}
function editProduct(d,sku,name,threshold,target){const p=d.products.find(x=>x.sku===sku);if(!p)return{ok:false,msg:'Product not found.'};
 const c={...p,name,threshold,target},e=checkProduct(d,c,true);if(e)return{ok:false,msg:e};Object.assign(p,c);return{ok:true,msg:'Saved '+sku+'.'}}
function moveStock(d,sku,type,qty,note){
 const p=d.products.find(x=>x.sku===sku);
 if(!p)return{ok:false,msg:'Choose a product first.'};
 if(!isInt(qty)||qty<=0)return{ok:false,msg:'Quantity must be a whole number greater than 0.'};
 if(type==='OUT'&&qty>p.qty)return{ok:false,msg:'Rejected: only '+p.qty+' available, cannot take out '+qty+'. Stock stays at '+p.qty+'.'};
 const after=type==='IN'?p.qty+qty:p.qty-qty; /* validated first, then both writes happen together */
 p.qty=after;d.moves.push({t:now(),sku,type,qty,after,note:note||''});
 return{ok:true,msg:'Recorded '+type+' '+qty+' for '+sku+'. Stock is now '+after+'.'}}

/* ---------- UI helpers ---------- */
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let tt;function toast(m,bad){const t=$('#toast');t.textContent=m;t.className='show'+(bad?' bad':'');clearTimeout(tt);tt=setTimeout(()=>t.className='',3800)}
const THEME_KEY='campus.stockroom.theme.v1';
const THEME_SWITCH='<span class="theme-switch" aria-hidden="true"><span class="theme-switch__container"><span class="theme-switch__clouds"></span><svg class="theme-switch__stars" viewBox="0 0 44 32"><path d="m8 2 1.7 4.3L14 8l-4.3 1.7L8 14l-1.7-4.3L2 8l4.3-1.7L8 2Zm23 3 1.4 3.6L36 10l-3.6 1.4L31 15l-1.4-3.6L26 10l3.6-1.4L31 5Zm-8 13 1.2 3.1L27 22l-2.8 1.1L23 26l-1.2-2.9L19 22l2.8-1.1L23 18Z"/><circle class="star-small" cx="15" cy="19" r="1"/><circle class="star-small" cx="40" cy="19" r="1.2"/><circle class="star-small" cx="19" cy="4" r=".8"/></svg><span class="theme-switch__circle-container"><span class="theme-switch__sun-moon"><span class="theme-switch__moon"><i></i></span></span></span></span></span>';
function setTheme(mode,persist){const light=mode==='light';document.body.classList.toggle('light',light);const label=light?'Dark mode':'Light mode';document.querySelectorAll('.theme-toggle').forEach(button=>{if(!button.querySelector('.theme-switch'))button.innerHTML=THEME_SWITCH;button.setAttribute('aria-checked',String(!light));button.setAttribute('aria-label','Switch to '+label.toLowerCase());button.title='Switch to '+label.toLowerCase()});if(persist){try{localStorage.setItem(THEME_KEY,light?'light':'dark')}catch(e){toast('Theme changed, but could not be saved.',true)}}}const num=id=>{const v=$(id).value.trim();return v===''?NaN:Number(v)};
const skuOpts=()=>db.products.map(p=>'<option value="'+esc(p.sku)+'">'+esc(p.sku)+' – '+esc(p.name)+'</option>').join('');
let tab='products',q='',editSku=null,pick=null,hf='';

const TABS=[['products','Products'],['move','Stock in/out'],['low','Low-stock report'],['reorder','Reorder'],['history','Movement history'],['proof','Test cases']];
function nav(){$('#nav').innerHTML=TABS.map(t=>'<button data-t="'+t[0]+'" class="'+(tab===t[0]?'on':'')+'">'+t[1]+'</button>').join('')}
$('#nav').onclick=e=>{const b=e.target.closest('button');if(b){tab=b.dataset.t;render()}};

function render(){nav();const v=$('#view');({products:vProducts,move:vMove,low:vLow,reorder:vReorder,history:vHistory,proof:vProof,about:vAbout})[tab](v)}

function vProducts(v){
 const e=db.products.find(p=>p.sku===editSku)||{sku:'',name:'',qty:0,threshold:5,target:20};
 const list=db.products.filter(p=>(p.sku+' '+p.name).toLowerCase().includes(q.toLowerCase()));
 v.innerHTML='<div class="panel"><h3>'+(editSku?'Edit '+esc(editSku):'Add a product')+'</h3><div class="row2">'+
 '<div><label>SKU</label><input id="fs" value="'+esc(e.sku)+'" '+(editSku?'readonly':'')+'></div>'+
 '<div style="flex:2"><label>Name</label><input id="fn" value="'+esc(e.name)+'"></div>'+
 (editSku?'':'<div><label>Opening stock</label><input id="fq" type="number" min="0" value="'+e.qty+'"></div>')+
 '<div><label>Minimum threshold</label><input id="ft" type="number" min="0" value="'+e.threshold+'"></div>'+
 '<div><label>Target stock</label><input id="fg" type="number" min="1" value="'+e.target+'"></div></div>'+
 '<div class="err" id="perr"></div><button id="sp">'+(editSku?'Save changes':'Add product')+'</button> '+(editSku?'<button class="ghost" id="cp">Cancel</button>':'')+'</div>'+
 '<div class="panel"><div class="row2"><h3 style="flex:2;margin:0">Products ('+list.length+')</h3><input id="sq" placeholder="Search by SKU or name" value="'+esc(q)+'"></div><div class="tw"><table><tr><th>SKU</th><th>Name</th><th class="n">Stock</th><th class="n">Threshold</th><th class="n">Target</th><th></th></tr>'+
 list.map(p=>'<tr class="'+(p.qty<=p.threshold?'low':'')+'"><td>'+esc(p.sku)+'</td><td>'+esc(p.name)+'</td><td class="n">'+p.qty+'</td><td class="n">'+p.threshold+'</td><td class="n">'+p.target+'</td><td><button class="ghost" data-e="'+esc(p.sku)+'">Edit</button></td></tr>').join('')+'</table></div></div>';
 $('#sp').onclick=()=>{const r=editSku?editProduct(db,editSku,$('#fn').value,num('#ft'),num('#fg')):addProduct(db,{sku:$('#fs').value.trim(),name:$('#fn').value,qty:num('#fq'),threshold:num('#ft'),target:num('#fg')});
  if(!r.ok){$('#perr').textContent=r.msg;toast(r.msg,1);return}save();editSku=null;toast(r.msg);render()};
 if($('#cp'))$('#cp').onclick=()=>{editSku=null;render()};
 $('#sq').oninput=e=>{q=e.target.value;const pos=e.target.selectionStart;vProducts(v);const s=$('#sq');s.focus();s.setSelectionRange(pos,pos)};
 v.querySelectorAll('[data-e]').forEach(b=>b.onclick=()=>{editSku=b.dataset.e;render();scrollTo({top:0,behavior:'smooth'})})}

function vMove(v){
 v.innerHTML='<div class="panel"><h3>Record stock-in or stock-out</h3><div class="row2"><div style="flex:2"><label>Product</label><select id="ms">'+skuOpts()+'</select></div>'+
 '<div><label>Type</label><select id="mt"><option value="IN">Stock in</option><option value="OUT">Stock out</option></select></div>'+
 '<div><label>Quantity</label><input id="mq" type="number" min="1" value="1"></div><div style="flex:2"><label>Note</label><input id="mn" placeholder="Delivery, class use, etc."></div></div>'+
 '<div class="err" id="merr"></div><button id="mb">Record movement</button></div><div class="panel grid" id="snap"></div>';
 const snap=()=>{const p=db.products.find(x=>x.sku===$('#ms').value);$('#snap').innerHTML=p?'<div class="stat"><b>'+p.qty+'</b><span>In stock</span></div><div class="stat"><b>'+p.threshold+'</b><span>Threshold</span></div><div class="stat"><b>'+p.target+'</b><span>Target</span></div><div class="stat"><b class="'+(reorder(p)?'warn':'ok')+'">'+reorder(p)+'</b><span>Suggested reorder</span></div>':''};
 $('#ms').onchange=snap;snap();
 $('#mb').onclick=()=>{const r=moveStock(db,$('#ms').value,$('#mt').value,num('#mq'),$('#mn').value);
  $('#merr').textContent=r.ok?'':r.msg;toast(r.msg,!r.ok);if(r.ok)save();else{$('#snap').classList.remove('shake');void $('#snap').offsetWidth;$('#snap').classList.add('shake')}snap()}}

function vLow(v){const L=db.products.filter(p=>p.qty<=p.threshold);
 v.innerHTML='<div class="panel"><h3>Low-stock report</h3>'+(L.length?'<div class="tw"><table><tr><th>SKU</th><th>Name</th><th class="n">Stock</th><th class="n">Threshold</th><th class="n">Short by</th></tr>'+L.map(p=>'<tr class="low"><td>'+esc(p.sku)+'</td><td>'+esc(p.name)+'</td><td class="n">'+p.qty+'</td><td class="n">'+p.threshold+'</td><td class="n">'+(p.threshold-p.qty+1>0?p.threshold-p.qty:0)+'</td></tr>').join('')+'</table></div>':'<p class="ok">Every item is above its threshold.</p>')+'</div>'}

function vReorder(v){const L=db.products.filter(p=>p.qty<=p.threshold);if(!pick||!db.products.some(p=>p.sku===pick))pick=db.products[0]&&db.products[0].sku;
 v.innerHTML='<div class="panel"><h3>Reorder suggestions</h3>'+(L.length?'<div class="tw"><table><tr><th>SKU</th><th>Name</th><th class="n">Stock</th><th class="n">Target</th><th class="n">Order</th></tr>'+L.map(p=>'<tr class="low"><td>'+esc(p.sku)+'</td><td>'+esc(p.name)+'</td><td class="n">'+p.qty+'</td><td class="n">'+p.target+'</td><td class="n"><span class="tag">'+reorder(p)+'</span></td></tr>').join('')+'</table></div>':'<p class="ok">Nothing to reorder right now.</p>')+'</div>'+
 '<div class="panel"><h3>How the decision is made</h3><label>Choose a product</label><select id="rs">'+skuOpts()+'</select><ol class="steps" id="rst"></ol></div>';
 $('#rs').value=pick;const f=()=>{pick=$('#rs').value;const p=db.products.find(x=>x.sku===pick);if(!p)return;const low=p.qty<=p.threshold;
  $('#rst').innerHTML='<li>Read the record: stock <b>'+p.qty+'</b>, threshold <b>'+p.threshold+'</b>, target <b>'+p.target+'</b>.</li><li>Check the rules: target must be greater than threshold ('+p.target+' &gt; '+p.threshold+') and stock cannot be negative.</li><li>Compare: is '+p.qty+' &lt;= '+p.threshold+'? <b class="'+(low?'warn':'ok')+'">'+(low?'Yes, the item is low':'No, the item is fine')+'</b>.</li><li>'+(low?'Calculate max(0, '+p.target+' &minus; '+p.qty+') = <b>'+reorder(p)+'</b>.':'No order is needed, so the recommendation is <b>0</b>.')+'</li>'};
 $('#rs').onchange=f;f()}

function vHistory(v){const M=db.moves.filter(m=>!hf||m.sku===hf).slice().reverse();
 v.innerHTML='<div class="panel"><div class="row2"><h3 style="margin:0;flex:2">Movement history</h3><select id="hs"><option value="">All products</option>'+skuOpts()+'</select></div><div class="tw"><table><tr><th>Time</th><th>SKU</th><th>Type</th><th class="n">Qty</th><th class="n">Stock after</th><th>Note</th></tr>'+
 M.map(m=>'<tr><td>'+esc(m.t)+'</td><td>'+esc(m.sku)+'</td><td class="'+(m.type==='IN'?'ok':'warn')+'">'+m.type+'</td><td class="n">'+m.qty+'</td><td class="n">'+m.after+'</td><td>'+esc(m.note)+'</td></tr>').join('')+'</table></div></div>';
 $('#hs').value=hf;$('#hs').onchange=e=>{hf=e.target.value;render()}}

function vAbout(v){v.innerHTML='<div class="panel about-panel"><h3>About StockNest</h3><div style="max-width:70ch;color:var(--dim)">'+ABOUT+'</div><h3 style="margin-top:20px">Website creators</h3><p style="margin-top:0;color:var(--dim)">This stockroom inventory tool was created by:</p><div class="creator-grid"><article class="creator-card"><img class="creator-photo" src="data:image/jpeg;base64," alt="Photo of Rean Albert G. Bersabe"><h4>Rean Albert G. Bersabe</h4><p>Website creator</p></article><article class="creator-card"><img class="creator-photo" src="data:image/jpeg;base64," alt="Photo of Ken D. Baga-an"><h4>Ken D. Baga-an</h4><p>Website creator</p></article><article class="creator-card"><div class="creator-avatar" aria-hidden="true">OL</div><h4>Orlando III Lapido</h4><p>Website creator</p></article></div></div>'}
function vProof(v){
 v.innerHTML='<div class="panel"><h3>Mandatory demonstration cases</h3><p style="color:var(--dim);margin-top:0">These run on a throw-away copy, so your real records are never touched.</p><button id="run">Run test cases</button><div id="res" style="margin-top:14px"></div></div>';
 $('#run').onclick=()=>{const d={products:[],moves:[]},R=[],add=(n,ok,det)=>R.push('<p><span class="'+(ok?'ok':'bad')+' mono">'+(ok?'PASS':'FAIL')+'</span> '+n+' <span style="color:var(--dim)">'+det+'</span></p>');
  addProduct(d,{sku:'T-1',name:'Test item',qty:4,threshold:5,target:20});
  add('Stock 4, threshold 5, target 20 gives reorder 16',reorder(d.products[0])===16,'got '+reorder(d.products[0]));
  const before=JSON.stringify(d),r1=moveStock(d,'T-1','OUT',8,'x');
  add('Stock-out of 8 when only 4 available is rejected',!r1.ok&&JSON.stringify(d)===before,'record unchanged, stock '+d.products[0].qty+', '+d.moves.length+' movement');
  const r2=addProduct(d,{sku:'T-2',name:'Bad',qty:1,threshold:10,target:10});add('Target not greater than threshold is rejected',!r2.ok&&d.products.length===1,r2.msg);
  const r3=addProduct(d,{sku:'T-3',name:'Neg',qty:-2,threshold:1,target:5});add('Negative opening stock is rejected',!r3.ok&&d.products.length===1,r3.msg);
  const r4=addProduct(d,{sku:'t-1',name:'Dup',qty:1,threshold:1,target:5});add('Duplicate SKU is rejected',!r4.ok&&d.products.length===1,r4.msg);
  const r5=moveStock(d,'T-1','OUT',4,'ok');add('Taking out exactly the available 4 is accepted',r5.ok&&d.products[0].qty===0,'stock now '+d.products[0].qty+', reorder '+reorder(d.products[0]));
  $('#res').innerHTML=R.join('')}}

