const UK='supply.users.v1';let activeUser='',umem=null,rec=null;
async function hash(s){try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch(e){return'p:'+s}}
async function users(){try{const r=JSON.parse(localStorage.getItem(UK));if(r){if(r.admin&&r.admin.pw===await hash('admin123'))delete r.admin;return r}}catch(e){}return umem||{}}
async function saveUsers(u){umem=u;try{localStorage.setItem(UK,JSON.stringify(u));return true}catch(e){return false}}
